// Node 89 - Turn the Calendly response into a list of selectable slots for node 91's
// dropdown. Stages calendly_slots, the boolean the router (node 92) tests, and an
// empty-state notice for when no times came back.
var times = (actions.calendly && actions.calendly.collection) || [];

var slots = [];
for (var i = 0; i < times.length; i++) {
  var t = times[i];
  var value = t.start_time || t.scheduling_url;
  if (value) slots.push({ label: t.start_time || value, value: value });
}

ZT.setTransformData("calendly_slots", slots);
ZT.setFormData("calendly_has_slots", slots.length > 0);
ZT.setTransformData("calendly_notice_html", slots.length ? "" :
  '<div style="border:1px solid #fed7aa;background:#fff7ed;border-radius:8px;padding:12px;color:#9a3412;font-size:14px;">No open Calendly times came back. Offer to take a preferred day/time and follow up.</div>');

26.content:
// Node 90 - Build the call summary for the End Call screen (summary_html) and the
// plain-text version for the copy-to-clipboard case note (summary_text).
function g(k){ return ZT.getVariableValue(k, ""); }

var rows = [
  ["Name", g("name")],
  ["Phone", g("phone")],
  ["Email", g("mail")],
  ["Address", g("address")],
  ["Company", g("company")],
  ["Case number", g("case_number")],
  ["Consultation reason", g("consult_reason")],
  ["Deadline", g("deadline")],
  ["Documents", g("docs")],
  ["Court date", g("court_date")],
  ["Interpreter confirmed", g("interpreter_confirmed")],
  ["Other caller type", g("other_type")],
  ["Acquaintance action", g("acquaintance_action")],
  ["Billing issue", g("billing_issue")],
  ["Consultation time", g("selected_time")],
  ["Notes", g("notes") || g("reason_notes") || g("billing_notes")]
];

var htmlRows = "", textLines = [];
for (var i = 0; i < rows.length; i++) {
  var label = rows[i][0], val = rows[i][1];
  if (!val) continue;
  htmlRows += '<tr><td style="padding:4px 12px 4px 0;color:#6b7280;white-space:nowrap;">' + label + '</td><td style="padding:4px 0;color:#111827;">' + val + '</td></tr>';
  textLines.push(label + ": " + val);
}
if (!htmlRows) {
  htmlRows = '<tr><td style="padding:4px 0;color:#6b7280;">No details captured on this call.</td></tr>';
  textLines.push("No details captured on this call.");
}

ZT.setTransformData("summary_html",
  '<div style="border:1px solid #c7d2fe;background:#eef2ff;border-radius:8px;padding:16px;font-family:-apple-system,Segoe UI,Roboto,sans-serif;max-width:520px;">' +
  '<div style="font-weight:600;color:#3730a3;margin-bottom:8px;">Call summary</div>' +
  '<table style="border-collapse:collapse;font-size:14px;">' + htmlRows + '</table></div>');
ZT.setTransformData("summary_text", textLines.join("\n"));
